class Command(BaseCommand):
    help = "Upgrade the RSRE Research Academy V41 learning content and beginner assessments."

    def handle(self, *args, **kwargs):
        for module in Module.objects.filter(active=True).order_by("level__number", "pathway_id", "order"):
            if module.title in LEVEL1:
                specs = LEVEL1[module.title]
            else:
                objectives = module.objectives or [module.summary or f"Understand {module.title}."]
                specs = [
                    ("Core concept", "text", f"{module.title} is taught from first principles. Start with what the term means, why it matters in health research, and where a student researcher would encounter it.\n\nKey learning point: {objectives[0]}\n\nBefore moving on, explain the idea in your own words and identify one situation where you would use it."),
                    ("Key ideas", "text", "Break the topic into its main parts. Define unfamiliar terms, identify the decision each part supports, and note one common beginner mistake. Keep the question, method, evidence and interpretation aligned."),
                    ("Worked example", "activity", f"Apply {module.title.lower()} to a realistic Rwanda/Africa health-research scenario. State the problem, explain what you would do, identify the evidence you would consult, and describe what you would document."),
                    ("Practice task", "activity", f"Write a short response showing how you would use {module.title.lower()} in a student research project. Focus on reasoning and application rather than advanced terminology."),
                    ("Check your understanding", "text", "You are ready for the basic assessment when you can explain the core idea without notes, identify a sensible example, and recognize a common mistake."),
                ]
            module.summary = module.summary or f"Build a practical understanding of {module.title.lower()} for health research."
            module.save(update_fields=["summary"])
            for order, (title, kind, body) in enumerate(specs, 1):
                Lesson.objects.update_or_create(module=module, order=order, defaults={
                    "title": title, "lesson_type": kind, "body": body, "video_url": "",
                    "resource_urls": [], "estimated_minutes": 30 if kind == "text" else 40,
                    "required": True, "active": True,
                })

            quiz, _ = Quiz.objects.update_or_create(module=module, defaults={
                "title": f"{module.title} - Basic Knowledge Check", "pass_mark": 80, "attempts_allowed": 0,
            })
            quiz.questions.all().delete()
            pool = [
                (f"What is the main purpose of learning {module.title.lower()}?", ["To understand and apply the core idea in health research", "To memorize advanced formulas immediately", "To choose results before data collection", "To avoid documenting decisions"], 0, "The first Academy check confirms basic understanding and responsible application."),
                ("What should a beginner do first when approaching a research task?", ["Define the problem or question clearly", "Choose a desired conclusion", "Skip existing evidence", "Copy another study without checking fit"], 0, "A clear problem or question gives the rest of the process direction."),
                ("Which action shows good research practice?", ["Make important decisions transparent and document them", "Change methods whenever the result is inconvenient", "Hide limitations", "Remove uncertain findings"], 0, "Transparent decisions support trustworthy research."),
                (f"Which statement best fits {module.title.lower()}?", ["The approach should match the research question and context", "One method is always correct", "More complicated is always better", "Results should be selected before analysis"], 0, "Research methods and decisions depend on the question and context."),
                ("What should you do when an important research claim is uncertain?", ["Verify it with appropriate evidence", "Publish it without checking", "Remove the uncertainty", "Treat an AI response as automatically correct"], 0, "Verification is a core research habit."),
                ("Why do researchers describe limitations?", ["So readers can judge how far the findings can be trusted", "To make the paper look weak", "Because every study must have negative findings", "To replace the results section"], 0, "Limitations explain uncertainty and boundaries."),
                ("Which is a good research habit?", ["Keep a record of important decisions and changes", "Change plans secretly", "Delete inconvenient observations", "Avoid keeping notes"], 0, "A clear record supports transparency and reproducibility."),
                ("How should evidence be judged?", ["For quality, relevance and limitations", "By popularity alone", "By one source only", "By whether it supports your preferred idea"], 0, "Evidence should be evaluated rather than simply collected."),
                ("When should ethics and governance be considered?", ["During planning, before activities that require approval", "Only after publication", "Only if results are interesting", "After recruitment is complete"], 0, "Ethics and governance are planning responsibilities."),
                ("What is the purpose of a worked example?", ["To show how the concept is applied in a realistic situation", "To replace the lesson", "To guarantee the same answer in every study", "To test advanced expertise"], 0, "Worked examples connect explanation to practical use."),
                ("What is the purpose of the basic knowledge check?", ["To confirm foundational understanding before progression", "To test whether the student already has professional expertise", "To guarantee publication", "To replace practical work"], 0, "Early assessments should confirm foundations."),
                ("If you are still unsure after the practice task, what is the best next step?", ["Review the relevant lesson and try again", "Guess and submit", "Skip the topic forever", "Choose the longest answer"], 0, "The Academy is designed around learning, practice and reassessment."),
            ]
            for i,(prompt,choices,correct,explanation) in enumerate(pool,1):
                q=Question.objects.create(quiz=quiz,order=i,prompt=prompt,question_type="single",explanation=explanation)
                for j,text in enumerate(choices,1): Choice.objects.create(question=q,order=j,text=text,is_correct=(j-1)==correct)

        DiagnosticAssessment.objects.update_or_create(id=1, defaults={
            "title": "Research Academy Entry Assessment",
            "description": "An optional beginner-friendly diagnostic used to recommend a starting point. It is not an advanced exam and does not replace module assessments.",
            "pass_mark": 70, "active": True, "questions": DIAGNOSTIC,
        })
        self.stdout.write(self.style.SUCCESS("RSRE Academy V41 content upgrade complete."))
